        File.WriteAllBytes(Path.Combine(folder,"app-icon.png"),Render(512));Showcase(folder);WriteSvg(folder);Console.WriteLine("PASS: generated ICO with 9 sizes, approved dark-background 512px preview, and light/dark showcase");return 0;
    }
    static void Text(DrawingContext dc,string text,double x,double y,double size,Brush brush) {dc.DrawText(new FormattedText(text,System.Globalization.CultureInfo.GetCultureInfo("zh-CN"),FlowDirection.LeftToRight,new Typeface("Microsoft YaHei UI"),size,brush),new Point(x,y));}
    static void Showcase(string folder) {
        var v=new DrawingVisual();using(var dc=v.RenderOpen()) {
            for(int panel=0;panel<2;panel++) {
                double x=panel*450;bool dark=panel==0;Brush ink=dark ? Brushes.White:new SolidColorBrush(Color.FromRgb(37,43,55));Brush muted=new SolidColorBrush(dark ? Color.FromRgb(158,165,179):Color.FromRgb(108,116,130));
                dc.DrawRectangle(new SolidColorBrush(dark ? Color.FromRgb(25,28,33):Color.FromRgb(243,245,249)),null,new Rect(x,0,450,470));
                Text(dc,dark ? "深色桌面":"浅色桌面",x+32,26,13,muted);
                dc.PushTransform(new TranslateTransform(x+145,65));dc.PushTransform(new ScaleTransform(160.0/256,160.0/256));DrawMark(dc,160);dc.Pop();dc.Pop();
                Text(dc,"TinyStar",x+168,240,26,ink);Text(dc,"桌面便签",x+188,280,15,muted);
                int[] sizes={16,24,32,48};double[] positions={76,154,237,326};
                for(int i=0;i<sizes.Length;i++) {int size=sizes[i];double sx=x+positions[i];dc.PushTransform(new TranslateTransform(sx-size/2.0,352-size/2.0));dc.PushTransform(new ScaleTransform(size/256.0,size/256.0));DrawMark(dc,size);dc.Pop();dc.Pop();Text(dc,size+" px",sx-17,391,11,muted);}
            }
        }
        var bitmap=new RenderTargetBitmap(900,470,96,96,PixelFormats.Pbgra32);bitmap.Render(v);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using(var file=File.Create(Path.Combine(folder,"icon-showcase.png")))png.Save(file);
    }
